import {getCurrentLocale} from '../utils.ts';

/** messages by CLDR plural category (zero/one/two/few/many/other), generated by backend `Locale.TrPluralForms` */
export type PluralForms = Partial<Record<Intl.LDMLPluralRule, string>>;

/** frontend `Locale.TrPlural`: pick the form of the CLDR plural category of `count` (fallback to `other`) and interpolate `%d` */
export function trPlural(count: number, forms: PluralForms, {lang = getCurrentLocale()}: {lang?: string} = {}): string {
  const text = forms[new Intl.PluralRules(lang).select(count)] ?? forms.other!;
  return trString(text, String(count));
}

/**
 * Fills variables in a translated string (like TrString in Golang)
 * Only `%s`, `%d` or one-based position like `%[1]s` are supported.
 */
export function trString(s: string, ...args: Array<string | number>) {
  // the same behavior (almost) as backend TrString
  let curIdx = 0;
  return s.replace(/%%|%(?:\[([1-9]\d*)\])?([sd])/g, (match, indexed: string) => {
    if (match === '%%') return '%';
    const argIndex = indexed ? Number(indexed) - 1 : curIdx++;
    if (argIndex < 0 || argIndex >= args.length) return match;
    return String(args[argIndex]);
  });
}
